sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float offset;
uniform float radius;
uniform float curlFrom;
uniform float direction;
uniform float stretch;
half4 main(float2 coord) {
    float2 p = coord;
    if (curlFrom < 0.5) p.x = size.x - p.x;
    if (direction > 0.5) p.y = size.y - p.y;
    float x0 = curlFrom < 0.5 ? size.x * (1.0 - offset) : size.x * offset;
    float yc = size.y * 0.5;
    float r = max(radius, 0.001) * size.y * 0.5;
    float k = max(stretch, 0.01) / r;
    float reach = size.x - x0;
    float2 c = float2(x0, yc - r);
    float2 d = p - c;
    float off = length(d) - r;
    float phi = atan(d.x, d.y);
    if (phi < 0.0) phi += 6.2831853;
    float2 src = float2(-1.0);
    if (abs(off) <= yc + 0.5 && reach > 0.0) {
        for (int m = 7; m >= 0; m--) {
            float along = (phi + 6.2831853 * float(m)) / k;
            if (along < reach) {
                src = float2(x0 + along, yc + off);
                break;
            }
        }
    }
    if (src.x < 0.0 && p.x <= x0) src = p;
    if (src.x < 0.0) return half4(0.0);
    if (curlFrom < 0.5) src.x = size.x - src.x;
    if (direction > 0.5) src.y = size.y - src.y;
    return image.eval(src);
}
